import os, sys, warnings, traceback
import numpy as np
import pandas as pd

USE_MFS = {"none": None, "true": True, "false": False}[sys.argv[1] if len(sys.argv) > 1 else "none"]
PBAR = (len(sys.argv) > 2 and sys.argv[2] == "pbar")

from pandarallel import pandarallel
pandarallel.initialize(nb_workers=2, progress_bar=PBAR, use_memory_fs=USE_MFS, verbose=0)

RESULTS = []


def describe(o):
    if isinstance(o, pd.DataFrame):
        return f"DataFrame shape={o.shape} idx={o.index!r} cols={list(o.columns)!r} dtypes={list(o.dtypes)!r}"
    if isinstance(o, pd.Series):
        return f"Series len={len(o)} name={o.name!r} idx={o.index!r} dtype={o.dtype}"
    return f"{type(o).__name__}: {o!r}"


def run(label, make_gb, func, *args, **kwargs):
    """make_gb() -> fresh groupby object"""
    seq_exc = par_exc = None
    seq = par = None
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", FutureWarning)
            warnings.simplefilter("ignore", DeprecationWarning)
            seq = make_gb().apply(func, *args, **kwargs)
    except Exception as e:
        seq_exc = e
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", FutureWarning)
            warnings.simplefilter("ignore", DeprecationWarning)
            par = make_gb().parallel_apply(func, *args, **kwargs)
    except Exception as e:
        par_exc = e

    if seq_exc is not None or par_exc is not None:
        if seq_exc is not None and par_exc is not None:
            ok = type(seq_exc).__name__ == type(par_exc).__name__
            note = f"both raised: seq={type(seq_exc).__name__}({seq_exc}) par={type(par_exc).__name__}({par_exc})"
        else:
            ok = False
            note = (f"ONLY SEQ RAISED {type(seq_exc).__name__}: {seq_exc}" if seq_exc
                    else f"ONLY PAR RAISED {type(par_exc).__name__}: {par_exc}")
        RESULTS.append((ok, label, note))
        return

    eq = False
    try:
        eq = bool(seq.equals(par))
    except Exception as e:
        eq = False
    same_type = type(seq) is type(par)
    idx_eq = True
    try:
        idx_eq = seq.index.equals(par.index)
    except Exception:
        idx_eq = False
    extra = ""
    if isinstance(seq, pd.DataFrame) and isinstance(par, pd.DataFrame):
        extra = f" cols_eq={seq.columns.equals(par.columns)} dtypes_eq={list(seq.dtypes)==list(par.dtypes)}"
    if isinstance(seq, pd.Series) and isinstance(par, pd.Series):
        extra = f" name_eq={seq.name == par.name} dtype_eq={seq.dtype == par.dtype}"
    ok = eq and same_type and idx_eq
    note = f"equals={eq} same_type={same_type} idx_eq={idx_eq}{extra}"
    if not ok:
        note += f"\n    SEQ: {describe(seq)}\n    PAR: {describe(par)}"
        note += f"\n    --- seq ---\n{seq}\n    --- par ---\n{par}"
    RESULTS.append((ok, label, note))


def report():
    print("\n" + "=" * 70)
    print(f"use_memory_fs={USE_MFS} progress_bar={PBAR}")
    bad = 0
    for ok, label, note in RESULTS:
        if not ok:
            bad += 1
            print(f"[FAIL] {label}: {note}")
    print(f"--- {len(RESULTS)} cases, {bad} failures ---")
    for ok, label, note in RESULTS:
        if ok:
            print(f"[ ok ] {label}: {note.splitlines()[0]}")
